import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:rattil/core/align/models.dart';
import 'package:rattil/core/align/phonetics.dart';
import 'package:rattil/core/align/session.dart';
import 'package:rattil/core/align/units.dart';

/// Per-word phonemes generated by quran-transcript (tool/spike/spike.py).
final Map<String, List<String>> ref = {
  for (final e in (jsonDecode(File('test/fixtures/reference_words.json').readAsStringSync()) as Map).entries)
    e.key as String: List<String>.from(e.value as List),
};

/// A 3-"ayah" test stream built from real phonemes: 1:1, 1:7, 2:255.
final List<String> words = [...ref['1:1']!, ...ref['1:7']!, ...ref['2:255']!];
final List<int> ayahOf = [
  ...List.filled(ref['1:1']!.length, 1),
  ...List.filled(ref['1:7']!.length, 2),
  ...List.filled(ref['2:255']!.length, 3),
];
final int a2 = ref['1:1']!.length; // first word of the 1:7 block
final int a3 = a2 + ref['1:7']!.length; // first word of the 2:255 block

TeacherSession session(int from, int to, {TeacherMode mode = TeacherMode.strict}) => TeacherSession(
      stream: ExpectedStream(words),
      rangeStart: from,
      rangeEnd: to,
      wordAyah: ayahOf,
      mode: mode,
    );

/// Feeds [text] as a growing ASR result, [chunk] characters at a time, then
/// twice more unchanged while the reader is silent. Stops at a StopEvent.
List<TeacherEvent> feed(TeacherSession s, String text, {int chunk = 6}) {
  final events = <TeacherEvent>[];
  for (var i = chunk; i < text.length + 2 * chunk; i += chunk) {
    final e = s.update(text.substring(0, i.clamp(0, text.length)), atPause: i >= text.length);
    events.addAll(e);
    if (e.any((x) => x is StopEvent || x is FinishedEvent)) break;
  }
  return events;
}

/// Changes the first single (not doubled) consonant of [word].
String wrongLetter(String word) {
  final chars = word.split('');
  bool single(int i) =>
      phoneticChars[chars[i]]?.kind == UnitKind.consonant &&
      (i == 0 || chars[i - 1] != chars[i]) &&
      (i == chars.length - 1 || chars[i + 1] != chars[i]);
  final i = List.generate(chars.length, (i) => i).firstWhere(single);
  chars[i] = chars[i] == 'ز' ? 'ب' : 'ز';
  return chars.join();
}

void main() {
  test('a correct reading finishes as Perfect with no other events', () {
    final s = session(a2, a3);
    final events = feed(s, words.sublist(a2, a3).join());
    expect(events, hasLength(1));
    expect((events.single as FinishedEvent).perfect, isTrue);
  });

  test('strict: a wrong letter stops at that word, then the reader repeats from it', () {
    final s = session(a2, a3);
    final heard = [...words.sublist(a2, a3)]..[3] = wrongLetter(words[a2 + 3]);
    final events = feed(s, heard.join());
    final stop = events.whereType<StopEvent>().single;
    expect(stop.word, a2 + 3);
    expect(stop.issue.type, IssueType.wrongLetter);
    expect(s.isPaused, isTrue);
    expect(s.update(heard.join()), isEmpty, reason: 'paused until resumeFrom');

    s.resumeFrom(stop.word);
    final after = feed(s, words.sublist(a2 + 3, a3).join());
    final done = after.whereType<FinishedEvent>().single;
    expect(done.perfect, isFalse, reason: 'a mistake was made in this session');
    expect(after.whereType<StopEvent>(), isEmpty);
  });

  test('gentle: a wrong letter is marked and the session goes on', () {
    final s = session(a2, a3, mode: TeacherMode.gentle);
    final heard = [...words.sublist(a2, a3)]..[3] = wrongLetter(words[a2 + 3]);
    final events = feed(s, heard.join());
    expect(events.whereType<MistakeEvent>().single.word, a2 + 3);
    expect(events.whereType<FinishedEvent>().single.perfect, isFalse);
  });

  test('strict: a skipped word stops', () {
    final s = session(a2, a3);
    final heard = [...words.sublist(a2, a2 + 4), ...words.sublist(a2 + 5, a3)];
    final stop = feed(s, heard.join()).whereType<StopEvent>().single;
    expect(stop.word, a2 + 4);
    expect(stop.issue.type, IssueType.missingWord);
  });

  test('a mistake on the last word is still caught', () {
    final s = session(a2, a3);
    final heard = [...words.sublist(a2, a3)]..[a3 - a2 - 1] = wrongLetter(words[a3 - 1]);
    final stop = feed(s, heard.join()).whereType<StopEvent>().single;
    expect(stop.word, a3 - 1);
  });

  test('repeating words is not a mistake', () {
    final s = session(a2, a3);
    final w = words.sublist(a2, a3);
    final events = feed(s, [w[0], w[1], w[2], w[1], w[2], ...w.skip(3)].join());
    expect(events.single, isA<FinishedEvent>());
    expect((events.single as FinishedEvent).perfect, isTrue);
  });

  test('a harakah slip never stops and blocks Perfect', () {
    final s = session(0, a2);
    final w = [...words.sublist(0, a2)];
    final chars = w[0].split('');
    final i = chars.indexWhere((c) => c == 'ِ');
    chars[i] = 'َ';
    w[0] = chars.join();
    final events = feed(s, w.join());
    expect(events.whereType<StopEvent>(), isEmpty);
    expect(events.whereType<FinishedEvent>().single.perfect, isFalse);
  });

  test('a jump forward is detected and the passed words are marked', () {
    final s = session(a3, words.length, mode: TeacherMode.gentle);
    final heard = [...words.sublist(a3, a3 + 5), ...words.sublist(a3 + 25, a3 + 35)];
    final events = feed(s, heard.join());
    final jump = events.whereType<JumpEvent>().first;
    expect(jump.toWord, inInclusiveRange(a3 + 24, a3 + 27));
    expect(jump.skippedFrom, a3 + 5);
    expect(s.results[a3 + 10]!.status, WordStatus.jumped);
  });

  test('noisy audio is not judged', () {
    final s = session(a2, a3)..noisy = true;
    final heard = [...words.sublist(a2, a3)]..[3] = wrongLetter(words[a2 + 3]);
    expect(feed(s, heard.join()), isEmpty);
    expect(s.results, isEmpty);
  });

  test('a whole long ayah in one update is not mistaken for a jump', () {
    final s = TeacherSession(
      stream: ExpectedStream(words),
      rangeStart: a3,
      rangeEnd: words.length,
      wordAyah: ayahOf,
      windowWords: 10,
    );
    final text = words.sublist(a3).join();
    final events = [...s.update(text, atPause: true), ...s.update(text, atPause: true)];
    expect(events.whereType<JumpEvent>(), isEmpty);
    expect(events.whereType<FinishedEvent>().single.perfect, isTrue);
  });

  test('a long range stays correct while the window moves forward', () {
    final s = session(a3, words.length);
    final events = feed(s, words.sublist(a3).join(), chunk: 10);
    expect(events.single, isA<FinishedEvent>());
    expect((events.single as FinishedEvent).perfect, isTrue);
  });
}
